from collections import Counter
def cleanfy(g):
    h,w=len(g),len(g[0])
    P={'H':lambda r,c:(r,w-1-c),'V':lambda r,c:(h-1-r,c),'R':lambda r,c:(h-1-r,w-1-c)}
    bad={(r,c) for r in range(h) for c in range(w)
         if any(g[r][c]!=g[pr][pc] for pr,pc in (P['H'](r,c),P['V'](r,c)))}
    out=[row[:] for row in g]
    for r,c in bad:
        vals=[g[pr][pc] for pr,pc in (P['H'](r,c),P['V'](r,c),P['R'](r,c)) if (pr,pc) not in bad]
        out[r][c]=Counter(vals).most_common(1)[0][0]
    return out,bad
